import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Box,
  CircularProgress,
  Paper,
  IconButton
} from '@mui/material';
import { Close as CloseIcon } from '@mui/icons-material';

export default function DocuSignModal({ open, onClose, onSigningComplete, formData }) {
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [signingUrl, setSigningUrl] = useState('');

  useEffect(() => {
    if (open) {
      // This will be replaced with actual DocuSign API call
      const initiateSigning = async () => {
        try {
          // TODO: Replace with actual API call to your backend
          // const response = await fetch('/api/docusign/envelope', {
          //   method: 'POST',
          //   headers: { 'Content-Type': 'application/json' },
          //   body: JSON.stringify({
          //     signerEmail: formData.email,
          //     signerName: `${formData.firstName} ${formData.lastName}`,
          //     clientUserId: formData.email // Using email as client user ID
          // })
          // });
          // const data = await response.json();
          // setSigningUrl(data.redirectUrl);

          // Simulated response for demo
          setTimeout(() => {
            setSigningUrl('https://demo.docusign.net/Signing/StartInSession.aspx?token=demo' + 
              `&name=${encodeURIComponent(formData.firstName + ' ' + formData.lastName)}` +
              `&email=${encodeURIComponent(formData.email)}`);
            setIsLoading(false);
          }, 1000);
        } catch (err) {
          console.error('Error initiating DocuSign:', err);
          setError('Failed to load document. Please try again.');
          setIsLoading(false);
        }
      };

      initiateSigning();
    }
  }, [open, formData]);

  const handleSigningComplete = () => {
    onSigningComplete();
    onClose();
  };

  if (!open) return null;

  return (
    <Dialog 
      open={open} 
      onClose={onClose}
      maxWidth="md"
      fullWidth
    >
      <DialogTitle>
        <Box display="flex" justifyContent="space-between" alignItems="center">
          <Typography variant="h6">Sign Service Agreement</Typography>
          <IconButton onClick={onClose} size="small">
            <CloseIcon />
          </IconButton>
        </Box>
      </DialogTitle>
      <DialogContent>
        {isLoading ? (
          <Box display="flex" justifyContent="center" my={4}>
            <CircularProgress />
            <Typography variant="body1" ml={2}>
              Preparing your document for signing...
            </Typography>
          </Box>
        ) : error ? (
          <Box textAlign="center" my={4}>
            <Typography color="error">{error}</Typography>
            <Button 
              variant="contained" 
              color="primary" 
              onClick={() => window.location.reload()}
              sx={{ mt: 2 }}
            >
              Try Again
            </Button>
          </Box>
        ) : (
          <Box>
            <Paper elevation={3} sx={{ p: 2, mb: 3 }}>
              <Typography variant="h6" gutterBottom>
                Service Agreement
              </Typography>
              <Typography paragraph>
                Please review and sign the service agreement to proceed with your appointment.
              </Typography>
              <Typography variant="body2" color="textSecondary">
                By signing, you agree to our terms of service and privacy policy.
              </Typography>
            </Paper>

            <Box textAlign="center" my={3}>
              <Button
                variant="contained"
                color="primary"
                size="large"
                onClick={() => {
                  window.open(signingUrl, '_blank');
                  // In a real app, you would set up a webhook or poll for completion
                  // For demo, we'll just proceed after a delay
                  setTimeout(handleSigningComplete, 2000);
                }}
                sx={{ minWidth: 200 }}
              >
                Sign Document
              </Button>
            </Box>
          </Box>
        )}
      </DialogContent>
      <DialogActions sx={{ p: 2 }}>
        <Button 
          onClick={onClose} 
          disabled={isLoading}
        >
          Cancel
        </Button>
      </DialogActions>
    </Dialog>
  );
}
